program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_divs = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    def spans(n, divs):
        out, start = [], 0
        for d in divs:
            if start < d:
                out.append((start, d))
            start = d + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = spans(h, row_divs), spans(w, col_divs)
    pattern = {}
    for r0, r1 in rs:
        for c0, c1 in cs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v != bg:
                        pattern[(r-r0, c-c0)] = v
    out = [row[:] for row in grid]
    for r0, r1 in rs:
        for c0, c1 in cs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = pattern.get((r-r0, c-c0), bg)
    return out
'''
